using System.Text.Json;
using Clary.Api.Identity;
using Npgsql;
using NpgsqlTypes;
namespace Clary.Api;

public sealed class EquipmentRepository(NpgsqlDataSource db) {
 static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 static void ReadAllowed(CompanyContext c){if(!AccountPermissions.Allows(c,CompanyCapability.Read))throw new CompanyDenied();}
 static string? Text(string? s,int max,bool required=false){s=s?.Trim();if(string.IsNullOrEmpty(s)){if(required)throw new ArgumentException("A name or title is required.");return null;}if(s.Length>max)throw new ArgumentException($"Text must be up to {max} characters.");return s;}
 static IReadOnlyList<EquipmentLine> ValidateLines(IReadOnlyList<EquipmentLine>? lines,AssetConfigurationDto config,IReadOnlyList<EquipmentLine>? previous){
  if(lines is null||lines.Count is <1 or >100)throw new ArgumentException("Add 1 to 100 equipment lines.");
  var result=new List<EquipmentLine>();var keys=new HashSet<string>();
  foreach(var l in lines){if(l is null||l.Quantity is <1 or >100)throw new ArgumentException("Choose a valid asset type and quantity 1 to 100.");var custom=Text(l.CustomCategory,100);
   var old=previous?.FirstOrDefault(p=>(l.AssetTypeId.HasValue?p.AssetTypeId==l.AssetTypeId:p.Category==l.Category)&&p.Quantity==l.Quantity&&string.Equals(p.CustomCategory,custom,StringComparison.OrdinalIgnoreCase));
   var type=AssetFieldValidation.Resolve(config,l.AssetTypeId,l.Category,old?.AssetTypeId,old?.Category);
   if(!keys.Add(type.Code+":"+custom?.ToUpperInvariant()))throw new ArgumentException("Duplicate equipment lines are not allowed.");result.Add(l with{Category=type.Code,CustomCategory=custom,AssetTypeId=type.Id});}return result;
 }
 static void Param(NpgsqlCommand q,string key,object? value,NpgsqlDbType type)=>q.Parameters.AddWithValue(key,type,value??DBNull.Value);
 static NpgsqlCommand Query(CompanyContext c,string sql,NpgsqlConnection conn,NpgsqlTransaction? tx=null)=>CompanyCommand.Create(c,sql,conn,tx);
 static async Task ActiveDirectory(CompanyContext c,string table,Guid? id,NpgsqlConnection conn,NpgsqlTransaction tx,CancellationToken ct){if(id is null)return;await using var q=Query(c,$"SELECT 1 FROM {table} WHERE company_id=@company AND id=@id AND active",conn,tx);q.Parameters.AddWithValue("id",id.Value);if(await q.ExecuteScalarAsync(ct) is null)throw new ArgumentException("Choose an active employee or department in this company.");}
 static IReadOnlyList<EquipmentLine> Lines(string json)=>JsonSerializer.Deserialize<EquipmentLine[]>(json,Json)!;
 sealed record Stock(Guid Id,string Category,string? CustomCategory,Guid? AssetTypeId);
 static bool Matches(Stock a,EquipmentLine l)=>(l.AssetTypeId.HasValue?a.AssetTypeId==l.AssetTypeId:a.Category==l.Category)&&(l.CustomCategory is null||string.Equals(a.CustomCategory?.Trim(),l.CustomCategory,StringComparison.OrdinalIgnoreCase));
 static List<Guid>? Allocate(IReadOnlyList<EquipmentLine> lines,List<Stock> stock){var chosen=new HashSet<Guid>();foreach(var l in lines.OrderBy(l=>l.CustomCategory is null?1:0).ThenBy(l=>l.Category,StringComparer.Ordinal).ThenBy(l=>l.CustomCategory,StringComparer.OrdinalIgnoreCase)){var ids=stock.Where(a=>!chosen.Contains(a.Id)&&Matches(a,l)).Take(l.Quantity).Select(a=>a.Id).ToArray();if(ids.Length!=l.Quantity)return null;chosen.UnionWith(ids);}return chosen.Order().ToList();}
 static async Task<List<Stock>> StockAsync(CompanyContext c,NpgsqlConnection conn,NpgsqlTransaction? tx,CancellationToken ct,bool locked=false,Guid? ticket=null){await using var q=Query(c,"SELECT id,category,custom_category,asset_type_id FROM inventory_assets WHERE company_id=@company AND status='Available' AND employee_id IS NULL AND nullif(btrim(assignee),'') IS NULL AND NOT EXISTS(SELECT 1 FROM ticket_asset_reservations r WHERE r.company_id=inventory_assets.company_id AND r.asset_id=inventory_assets.id AND (@ticket IS NULL OR r.ticket_id<>@ticket)) ORDER BY CASE WHEN EXISTS(SELECT 1 FROM ticket_asset_reservations r WHERE r.company_id=inventory_assets.company_id AND r.asset_id=inventory_assets.id AND r.ticket_id=@ticket) THEN 0 ELSE 1 END,id"+(locked?" FOR UPDATE":""),conn,tx);Param(q,"ticket",ticket,NpgsqlDbType.Uuid);await using var r=await q.ExecuteReaderAsync(ct);var a=new List<Stock>();while(await r.ReadAsync(ct))a.Add(new(r.GetGuid(0),r.GetString(1),r.IsDBNull(2)?null:r.GetString(2),r.IsDBNull(3)?null:r.GetGuid(3)));return a;}
 static int Fulfillable(IReadOnlyList<EquipmentLine> lines,List<Stock> stock){if(lines.Count==0)return 0;var bound=stock.Count/lines.Sum(l=>l.Quantity);foreach(var group in lines.GroupBy(l=>l.Category)){bound=Math.Min(bound,stock.Count(a=>a.Category==group.Key)/group.Sum(l=>l.Quantity));foreach(var line in group.Where(l=>l.CustomCategory is not null))bound=Math.Min(bound,stock.Count(a=>Matches(a,line))/line.Quantity);}return bound;}
 static EquipmentKit Kit(NpgsqlDataReader r,List<Stock> stock){var lines=Lines(r.GetString(5));var count=Fulfillable(lines,stock);return new(r.GetGuid(0),r.GetString(1),r.IsDBNull(2)?null:r.GetGuid(2),r.GetBoolean(3),r.GetInt32(4),lines,lines.Select(l=>new EquipmentAvailability(l.Category,l.CustomCategory,l.Quantity,stock.Count(a=>Matches(a,l)),l.AssetTypeId)).ToArray(),count>0,count);}
 const string KitColumns="id,name,department_id,active,revision,lines::text";
 async Task<EquipmentKit?> GetKit(CompanyContext c,Guid id,NpgsqlConnection conn,NpgsqlTransaction? tx,CancellationToken ct){var stock=await StockAsync(c,conn,tx,ct);await using var q=Query(c,$"SELECT {KitColumns} FROM equipment_kits WHERE company_id=@company AND id=@id",conn,tx);q.Parameters.AddWithValue("id",id);await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?Kit(r,stock):null;}
 public async Task<EquipmentKit?> GetKitAsync(CompanyContext c,Guid id,CancellationToken ct){ReadAllowed(c);await using var conn=await db.OpenConnectionAsync(ct);return await GetKit(c,id,conn,null,ct);}
 public async Task<IReadOnlyList<EquipmentKit>> ListKitsAsync(CompanyContext c,CancellationToken ct){ReadAllowed(c);await using var conn=await db.OpenConnectionAsync(ct);var stock=await StockAsync(c,conn,null,ct);await using var q=Query(c,$"SELECT {KitColumns} FROM equipment_kits WHERE company_id=@company ORDER BY name,id",conn);await using var r=await q.ExecuteReaderAsync(ct);var result=new List<EquipmentKit>();while(await r.ReadAsync(ct))result.Add(Kit(r,stock));return result;}
 public async Task<EquipmentKit> SaveKitAsync(CompanyContext c,Guid? id,EquipmentKitInput input,CancellationToken ct){
  var name=Text(input.Name,100,true)!;if(id.HasValue&&input.Revision is not >0)throw new ArgumentException("Reload the kit before saving.");
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);await AccountPermissions.RevalidateAsync(conn,tx,c,CompanyCapability.Write,ct);await ActiveDirectory(c,"inventory_departments",input.DepartmentId,conn,tx,ct);
  var before=id.HasValue?await GetKit(c,id.Value,conn,tx,ct):null;if(id.HasValue&&before is null)throw new InventoryMissing();if(before is not null&&before.Revision!=input.Revision)throw new InventoryConflict("This kit was updated elsewhere. Reopen it before saving.");var key=id??Guid.NewGuid();
  var lines=ValidateLines(input.Lines,await AssetConfigurationRepository.Read(conn,tx,c,ct),before?.Lines);
  await using(var q=Query(c,id.HasValue?"UPDATE equipment_kits SET name=@name,department_id=@department,active=@active,lines=@lines,revision=revision+1 WHERE company_id=@company AND id=@id AND revision=@revision":"INSERT INTO equipment_kits(id,company_id,name,department_id,active,lines) VALUES(@id,@company,@name,@department,@active,@lines)",conn,tx)){q.Parameters.AddWithValue("id",key);q.Parameters.AddWithValue("name",name);Param(q,"department",input.DepartmentId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("active",input.Active);q.Parameters.AddWithValue("lines",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(lines,Json));if(id.HasValue)q.Parameters.AddWithValue("revision",input.Revision!.Value);if(await q.ExecuteNonQueryAsync(ct)!=1)throw new InventoryConflict("Reload the kit before saving.");}
  var after=(await GetKit(c,key,conn,tx,ct))!;await AuditRepository.AppendAsync(conn,tx,c,id.HasValue?"Updated":"Created","equipment-kit",key,before,after,ct);await tx.CommitAsync(ct);return after;
 }
 public async Task<object> DeleteKitAsync(CompanyContext c,Guid id,EquipmentKitDeletion input,CancellationToken ct){
  if(input.Revision<1)throw new ArgumentException("Reload the kit before deleting.");
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);await AccountPermissions.RevalidateAsync(conn,tx,c,CompanyCapability.Delete,ct);
  var before=await GetKit(c,id,conn,tx,ct)??throw new InventoryMissing();if(before.Revision!=input.Revision)throw new InventoryConflict("This kit changed. Refresh kits before deleting.");
  await using(var linked=Query(c,"SELECT 1 FROM equipment_requests WHERE company_id=@company AND kit_id=@id UNION ALL SELECT 1 FROM ticket_templates WHERE company_id=@company AND kit_id=@id LIMIT 1",conn,tx)){linked.Parameters.AddWithValue("id",id);if(await linked.ExecuteScalarAsync(ct) is not null)throw new InventoryConflict("This kit is linked to requests or ticket templates. Archive it or update its templates before deleting.");}
  await using(var q=Query(c,"DELETE FROM equipment_kits WHERE company_id=@company AND id=@id AND revision=@revision",conn,tx)){q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("revision",input.Revision);if(await q.ExecuteNonQueryAsync(ct)!=1)throw new InventoryConflict("This kit changed. Refresh kits before deleting.");}
  var after=new{Id=id,Deleted=true,Revision=before.Revision+1};await AuditRepository.AppendAsync(conn,tx,c,"Deleted","equipment-kit",id,before,after,ct);await tx.CommitAsync(ct);return after;
 }
 const string RequestColumns="id,title,employee_id,department_id,kit_id,kit_name,needed_date,notes,state,ticket_id,revision,created_at,lines::text,purpose,location_id";
 static EquipmentRequest Request(NpgsqlDataReader r)=>new(r.GetGuid(0),r.GetString(1),r.GetGuid(2),r.IsDBNull(3)?null:r.GetGuid(3),r.GetGuid(4),r.GetString(5),r.IsDBNull(6)?null:r.GetFieldValue<DateOnly>(6),r.IsDBNull(7)?null:r.GetString(7),r.GetString(8),r.GetGuid(9),r.GetInt32(10),r.GetDateTime(11),Lines(r.GetString(12)),[],r.GetString(13),r.IsDBNull(14)?null:r.GetGuid(14));
 async Task<EquipmentRequest?> GetRequest(CompanyContext c,Guid id,NpgsqlConnection conn,NpgsqlTransaction? tx,CancellationToken ct){EquipmentRequest? row;await using(var q=Query(c,$"SELECT {RequestColumns} FROM equipment_requests WHERE company_id=@company AND id=@id",conn,tx)){q.Parameters.AddWithValue("id",id);await using var r=await q.ExecuteReaderAsync(ct);row=await r.ReadAsync(ct)?Request(r):null;}if(row is null)return null;await using var assets=Query(c,"SELECT asset_id FROM equipment_request_assets WHERE company_id=@company AND request_id=@id ORDER BY asset_id",conn,tx);assets.Parameters.AddWithValue("id",id);await using var reader=await assets.ExecuteReaderAsync(ct);var ids=new List<Guid>();while(await reader.ReadAsync(ct))ids.Add(reader.GetGuid(0));return row with{AssetIds=ids};}
 public async Task<EquipmentRequest?> GetRequestAsync(CompanyContext c,Guid id,CancellationToken ct){ReadAllowed(c);await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(System.Data.IsolationLevel.RepeatableRead,ct);return await GetRequest(c,id,conn,tx,ct);}
 public async Task<IReadOnlyList<EquipmentRequest>> ListRequestsAsync(CompanyContext c,CancellationToken ct){ReadAllowed(c);await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(System.Data.IsolationLevel.RepeatableRead,ct);var ids=new List<Guid>();await using(var q=Query(c,"SELECT id FROM equipment_requests WHERE company_id=@company ORDER BY created_at DESC,id",conn,tx)){await using var r=await q.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))ids.Add(r.GetGuid(0));}var rows=new List<EquipmentRequest>();foreach(var id in ids)rows.Add((await GetRequest(c,id,conn,tx,ct))!);return rows;}
 public async Task<EquipmentTicket?> GetTicketAsync(CompanyContext c,Guid id,CancellationToken ct){ReadAllowed(c);await using var q=CompanyCommand.Create(c,"SELECT id,request_id,title,CASE state WHEN 'Assigned' THEN 'Ready' WHEN 'In Progress' THEN 'Ready' WHEN 'Complete' THEN 'Completed' WHEN 'Canceled' THEN 'Cancelled' ELSE state END,revision,created_at,updated_at FROM equipment_tickets WHERE company_id=@company AND id=@id",db);q.Parameters.AddWithValue("id",id);await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetInt32(4),r.GetDateTime(5),r.GetDateTime(6)):null;}
 public async Task<EquipmentRequest> CreateRequestAsync(CompanyContext c,EquipmentRequestInput input,CancellationToken ct){
  if(input.Purpose is not("Equipment" or "Onboarding"))throw new ArgumentException("Choose a valid request purpose.");if(input.Purpose=="Onboarding"&&input.NeededDate is null)throw new ArgumentException("Choose a start date for onboarding.");var title=Text(input.Title,200,true)!;var notes=Text(input.Notes,4000);await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);await AccountPermissions.RevalidateAsync(conn,tx,c,CompanyCapability.Write,ct);if(input.ImmediateAssignment)await AccountPermissions.RevalidateAsync(conn,tx,c,CompanyCapability.Approve,ct);
  await ActiveDirectory(c,"locations",input.LocationId,conn,tx,ct);await ActiveDirectory(c,"employees",input.EmployeeId,conn,tx,ct);await ActiveDirectory(c,"inventory_departments",input.DepartmentId,conn,tx,ct);var kit=await GetKit(c,input.KitId,conn,tx,ct)??throw new InventoryMissing();if(!kit.Active)throw new ArgumentException("Choose an active kit.");if(kit.DepartmentId.HasValue&&kit.DepartmentId!=input.DepartmentId)throw new ArgumentException("This kit belongs to another department.");
  var id=Guid.NewGuid();var ticket=Guid.NewGuid();
  await using(var q=Query(c,"INSERT INTO equipment_tickets(id,company_id,request_id,title,state) VALUES(@ticket,@company,@id,@title,'Pending'); INSERT INTO equipment_requests(id,company_id,title,employee_id,department_id,kit_id,kit_name,needed_date,notes,state,ticket_id,lines,purpose,location_id) VALUES(@id,@company,@title,@employee,@department,@kit,@kitName,@date,@notes,'Pending',@ticket,@lines,@purpose,@location)",conn,tx)){q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("ticket",ticket);q.Parameters.AddWithValue("title",title);q.Parameters.AddWithValue("employee",input.EmployeeId);Param(q,"department",input.DepartmentId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("kit",kit.Id);q.Parameters.AddWithValue("kitName",kit.Name);Param(q,"date",input.NeededDate,NpgsqlDbType.Date);Param(q,"notes",notes,NpgsqlDbType.Text);q.Parameters.AddWithValue("purpose",input.Purpose);Param(q,"location",input.LocationId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("lines",NpgsqlDbType.Jsonb,JsonSerializer.Serialize(kit.Lines,Json));await q.ExecuteNonQueryAsync(ct);}
  var request=(await GetRequest(c,id,conn,tx,ct))!;await new TicketRepository(db).AdoptRequest(conn,tx,c,request,"Created",ct);await AuditRepository.AppendAsync(conn,tx,c,"Created","equipment-request",id,null,request,ct);await AuditRepository.AppendAsync(conn,tx,c,"Created","equipment-ticket",ticket,null,new{Id=ticket,RequestId=id,Title=title,State="Pending",Revision=1},ct);
  if(input.ImmediateAssignment)request=await Transition(c,request,new("approve-and-assign",1),conn,tx,ct);await tx.CommitAsync(ct);return request;
 }
 public async Task<EquipmentRequest> ActionAsync(CompanyContext c,Guid id,EquipmentAction action,CancellationToken ct){if(action.Revision<1)throw new ArgumentException("Reload the request before acting.");await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);await AccountPermissions.RevalidateAsync(conn,tx,c,action.Action=="cancel"?CompanyCapability.Write:CompanyCapability.Approve,ct);var before=await GetRequest(c,id,conn,tx,ct)??throw new InventoryMissing();var after=await Transition(c,before,action,conn,tx,ct);await tx.CommitAsync(ct);return after;}
 async Task<EquipmentRequest> Transition(CompanyContext c,EquipmentRequest before,EquipmentAction action,NpgsqlConnection conn,NpgsqlTransaction tx,CancellationToken ct){
  if(before.Revision!=action.Revision)throw new InventoryConflict("This request changed. Reopen it before acting.");if(action.Action is "complete" or "cancel"){await new TicketRepository(db).RequestAction(conn,tx,c,before.TicketId,action.Action,ct);return (await GetRequest(c,before.Id,conn,tx,ct))!;}var state=action.Action switch{"approve" when before.State=="Pending"=>"Approved","assign" when before.State=="Approved"=>"Ready","approve-and-assign" when before.State=="Pending"=>"Ready","complete" when before.State=="Ready"=>"Completed","cancel" when before.State is "Pending" or "Approved" &&before.AssetIds.Count==0=>"Cancelled",_=>throw new InventoryConflict("This action is not available in the current request state.")};
  if(state=="Ready"){
   await ActiveDirectory(c,"employees",before.EmployeeId,conn,tx,ct);await ActiveDirectory(c,"inventory_departments",before.DepartmentId,conn,tx,ct);
   var stock=await StockAsync(c,conn,tx,ct,true,before.TicketId);await ActiveDirectory(c,"locations",before.LocationId,conn,tx,ct);if(action.AssetIds is {} selected){if(selected.Count!=before.Lines.Sum(l=>l.Quantity)||selected.Distinct().Count()!=selected.Count)throw new InventoryConflict("Choose exactly the required number of distinct available assets.");stock=stock.Where(a=>selected.Contains(a.Id)).ToList();}var chosen=Allocate(before.Lines,stock)??throw new InventoryConflict("Insufficient available stock for the complete kit. Save Pending or replenish stock before assigning.");
   foreach(var asset in chosen){var old=await AuditRepository.SnapshotAsync(conn,tx,c,"inventory_assets","id",asset,ct);await using(var q=Query(c,"UPDATE inventory_assets SET employee_id=@employee,assignee=(SELECT display_name FROM employees WHERE company_id=@company AND id=@employee),department_id=@department,department=(SELECT name FROM inventory_departments WHERE company_id=@company AND id=@department),location_id=COALESCE(@location,location_id),location=CASE WHEN @location IS NULL THEN location ELSE (SELECT name FROM locations WHERE company_id=@company AND id=@location) END,status='Assigned',revision=revision+1,updated_at=now() WHERE company_id=@company AND id=@asset AND status='Available' AND employee_id IS NULL AND nullif(btrim(assignee),'') IS NULL; INSERT INTO equipment_request_assets(company_id,request_id,asset_id) VALUES(@company,@request,@asset); INSERT INTO inventory_activity(company_id,id,asset_id,computer,kind) SELECT @company,@activity,id,computer,'Assigned' FROM inventory_assets WHERE company_id=@company AND id=@asset; DELETE FROM directory_mapping_review WHERE company_id=@company AND asset_id=@asset AND kind IN ('employee','department')",conn,tx)){Param(q,"location",before.LocationId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("employee",before.EmployeeId);Param(q,"department",before.DepartmentId,NpgsqlDbType.Uuid);q.Parameters.AddWithValue("asset",asset);q.Parameters.AddWithValue("request",before.Id);q.Parameters.AddWithValue("activity",Guid.NewGuid());await q.ExecuteNonQueryAsync(ct);}var current=await AuditRepository.SnapshotAsync(conn,tx,c,"inventory_assets","id",asset,ct);await AuditRepository.AppendAsync(conn,tx,c,"Assigned","asset",asset,old,current,ct,before.TicketId);}
  }
  var oldTicket=await AuditRepository.SnapshotAsync(conn,tx,c,"equipment_tickets","id",before.TicketId,ct);
  await using(var q=Query(c,"UPDATE equipment_requests SET state=@state,revision=revision+1 WHERE company_id=@company AND id=@id AND revision=@revision; UPDATE equipment_tickets SET state=@state,revision=revision+1,updated_at=now() WHERE company_id=@company AND id=@ticket",conn,tx)){q.Parameters.AddWithValue("state",state);q.Parameters.AddWithValue("id",before.Id);q.Parameters.AddWithValue("revision",before.Revision);q.Parameters.AddWithValue("ticket",before.TicketId);await q.ExecuteNonQueryAsync(ct);}
  var after=(await GetRequest(c,before.Id,conn,tx,ct))!;await new TicketRepository(db).AdoptRequest(conn,tx,c,after,action.Action,ct);await AuditRepository.AppendAsync(conn,tx,c,action.Action,"equipment-request",before.Id,before,after,ct);await AuditRepository.AppendAsync(conn,tx,c,action.Action,"equipment-ticket",before.TicketId,oldTicket,await AuditRepository.SnapshotAsync(conn,tx,c,"equipment_tickets","id",before.TicketId,ct),ct);return after;
 }
}


